const targetSet = (kind, label) => [1, 2, 3].map(number => ({ id: `${kind}-${number}`, label: `${label} ${number}`, kind }));
const choice = (prefix, id, label) => ({ id, label, narration: `adventure_${prefix}_choice_${id}` });
function adventure(prefix, kind, targetLabel, secretKind, secretLabel, choices, answer) {
  const narrationId = field => `adventure_${prefix}_${field}`;
  return {
    id: prefix, title: narrationId('title'), instruction: narrationId('instruction'), complete: narrationId('complete'),
    secretHint: narrationId('secretHint'), secretFound: narrationId('secretFound'),
    bonusQuestion: narrationId('bonusQuestion'), bonusHint: narrationId('bonusHint'), bonusCorrect: narrationId('bonusCorrect'),
    targets: targetSet(kind, targetLabel), secret: { id: secretKind, label: secretLabel, kind: secretKind },
    bonus: { choices: choices.map(([id, label]) => choice(prefix, id, label)), answer },
  };
}

